import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;

/** Export/restore Kotlin class annotations as reviewed text; never import original method code. */
public final class RestoreKotlinClassMetadata {
 static String encode(String value){byte[] bytes=new byte[value.length()*2];for(int i=0;i<value.length();i++){bytes[2*i]=(byte)(value.charAt(i)>>>8);bytes[2*i+1]=(byte)value.charAt(i);}return Base64.getEncoder().encodeToString(bytes);}
 static String decode(String value){byte[] bytes=Base64.getDecoder().decode(value);if(bytes.length%2!=0)throw new IllegalArgumentException("UTF16 code units");char[] chars=new char[bytes.length/2];for(int i=0;i<chars.length;i++)chars[i]=(char)((bytes[2*i]&255)<<8|(bytes[2*i+1]&255));return new String(chars);}
 static String[] encodeValue(Object value){if(value instanceof Integer integer)return new String[]{"i",integer.toString()};if(value instanceof String string)return new String[]{"s",encode(string)};if(value instanceof List<?> list){if(list.stream().allMatch(x->x instanceof Integer))return new String[]{"ai",list.size()+":"+String.join(",",list.stream().map(Object::toString).toList())};if(list.stream().allMatch(x->x instanceof String))return new String[]{"as",list.size()+":"+String.join(",",list.stream().map(x->encode((String)x)).toList())};}throw new IllegalArgumentException("Unsupported Kotlin metadata element "+value);}
 static Object decodeValue(String type,String value){if(type.equals("i"))return Integer.valueOf(value);if(type.equals("s"))return decode(value);int colon=value.indexOf(':');int count=Integer.parseInt(value.substring(0,colon));String[] parts=count==0?new String[0]:value.substring(colon+1).split(",",-1);if(parts.length!=count)throw new IllegalArgumentException("Metadata array count");List<Object> list=new ArrayList<>();for(String part:parts)list.add(type.equals("ai")?Integer.valueOf(part):decode(part));if(!type.equals("ai")&&!type.equals("as"))throw new IllegalArgumentException("Metadata type");return list;}
 public static void main(String[] args)throws Exception{
  if(args[0].equals("--export")){Set<String> owners=new TreeSet<>(Files.readAllLines(Path.of(args[2])));List<String> rows=new ArrayList<>();try(ZipFile jar=new ZipFile(args[1])){for(String owner:owners){ClassNode node=new ClassNode();new ClassReader(jar.getInputStream(jar.getEntry(owner+".class"))).accept(node,ClassReader.SKIP_CODE|ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);List<AnnotationNode> annotations=node.visibleAnnotations==null?List.of():node.visibleAnnotations;AnnotationNode metadata=annotations.stream().filter(a->a.desc.equals("Lkotlin/Metadata;")).findFirst().orElseThrow();for(int i=0;i<metadata.values.size();i+=2){String[] value=encodeValue(metadata.values.get(i+1));rows.add(String.join("\t",owner,(String)metadata.values.get(i),value[0],value[1]));}}}Files.write(Path.of(args[3]),rows);System.out.println("Exported Kotlin annotation owners="+owners.size());return;}
  if(!args[0].equals("--restore"))throw new IllegalArgumentException("--export/--restore");Map<String,List<Object>> metadata=new LinkedHashMap<>();for(String row:Files.readAllLines(Path.of(args[2]))){String[] cells=row.split("\t",-1);if(cells.length!=4)throw new IllegalArgumentException("Metadata row");List<Object> values=metadata.computeIfAbsent(cells[0],key->new ArrayList<>());if(values.contains(cells[1]))throw new IllegalArgumentException("Duplicate annotation element");values.add(cells[1]);values.add(decodeValue(cells[2],cells[3]));}
  Path root=Path.of(args[1]);for(var entry:metadata.entrySet()){Path path=root.resolve(entry.getKey()+".class");ClassNode node=new ClassNode();new ClassReader(Files.readAllBytes(path)).accept(node,0);if(!node.name.equals(entry.getKey()))throw new IllegalStateException("Annotation owner mismatch");if(node.visibleAnnotations==null)node.visibleAnnotations=new ArrayList<>();node.visibleAnnotations.removeIf(a->a.desc.equals("Lkotlin/Metadata;"));AnnotationNode annotation=new AnnotationNode("Lkotlin/Metadata;");annotation.values=entry.getValue();node.visibleAnnotations.add(annotation);ClassWriter writer=new ClassWriter(0);node.accept(writer);Files.write(path,writer.toByteArray());}System.out.println("Restored Kotlin annotation owners="+metadata.size());
 }
}
